CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE TABLE public.employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 100), active boolean NOT NULL DEFAULT true);
GRANT SELECT(id,name) ON public.employees TO anon;
GRANT SELECT,INSERT,UPDATE ON public.employees TO authenticated;
GRANT ALL ON public.employees TO service_role;
ALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;
CREATE POLICY active_employees ON public.employees FOR SELECT TO anon USING(active);
CREATE POLICY admin_employees ON public.employees FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.incident_types (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 160), active boolean NOT NULL DEFAULT true);
GRANT SELECT(id,name) ON public.incident_types TO anon;
GRANT SELECT,INSERT,UPDATE ON public.incident_types TO authenticated;
GRANT ALL ON public.incident_types TO service_role;
ALTER TABLE public.incident_types ENABLE ROW LEVEL SECURITY;
CREATE POLICY active_types ON public.incident_types FOR SELECT TO anon USING(active);
CREATE POLICY admin_types ON public.incident_types FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid NOT NULL REFERENCES public.employees(id), incident_type_id uuid NOT NULL REFERENCES public.incident_types(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT(employee_id,incident_type_id) ON public.incidents TO anon,authenticated;
GRANT SELECT ON public.incidents TO authenticated;
GRANT ALL ON public.incidents TO service_role;
ALTER TABLE public.incidents ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_insert ON public.incidents FOR INSERT TO anon,authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.employees WHERE id=employee_id AND active) AND EXISTS(SELECT 1 FROM public.incident_types WHERE id=incident_type_id AND active));
CREATE POLICY admin_read ON public.incidents FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.validate_incident() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.employees WHERE id=NEW.employee_id AND active FOR SHARE) OR NOT EXISTS(SELECT 1 FROM public.incident_types WHERE id=NEW.incident_type_id AND active FOR SHARE) THEN RAISE EXCEPTION 'Empleado o incidente inactivo'; END IF; NEW.created_at=now(); RETURN NEW; END $$;
CREATE TRIGGER validate_incident_before BEFORE INSERT ON public.incidents FOR EACH ROW EXECUTE FUNCTION public.validate_incident();
CREATE INDEX incidents_created_at ON public.incidents(created_at);
